import React from 'react';
import { Upload } from 'lucide-react';

export const WelcomeScreen = ({ onFileUpload, fileInputRef }) => {
  return (
    <div className="flex flex-col items-center justify-center h-full text-center p-6">
      <div className="mb-6">
        <Upload className="w-20 h-20 text-indigo-400 mx-auto mb-4" />
      </div>
      <h2 className="text-2xl font-bold text-gray-800 mb-3">
        Welcome to Your Interview!
      </h2>
      <p className="text-gray-600 mb-8 max-w-md">
        Upload your resume (PDF or DOCX) to begin the interview process. 
        We'll extract your information and get started right away.
      </p>
      <button
        onClick={() => fileInputRef.current?.click()}
        className="bg-indigo-600 text-white px-8 py-3 rounded-lg hover:bg-indigo-700 transition font-medium shadow-lg hover:shadow-xl transform hover:-translate-y-0.5"
      >
        Upload Resume
      </button>
      <input
        ref={fileInputRef}
        type="file"
        accept=".pdf,.docx"
        onChange={onFileUpload}
        className="hidden"
      />
      <div className="mt-8 text-sm text-gray-500">
        <p>Supported formats: PDF, DOCX</p>
      </div>
    </div>
  );
};
